from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    outside = [[False] * w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True; q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == 0 and not outside[r][c]:
                outside[r][c] = True; q.append((r,c))
    # Orthogonal connectivity determines whether a zero region is enclosed.
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and not outside[rr][cc]:
                outside[rr][cc]=True; q.append((rr,cc))
    interior={(r,c) for r in range(h) for c in range(w) if grid[r][c]==0 and not outside[r][c]}
    if not interior:
        return out
    walls=set()
    # Color the zero-side rim bordering a cavity, and collect its wall pixels.
    for r,c in interior:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                if dr == dc == 0: continue
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and grid[rr][cc]==1:
                    out[r][c]=3
                    walls.add((rr,cc))
    # Follow the connected line outline(s) enclosing the cavity.
    q=deque(walls)
    while q:
        r,c=q.popleft()
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            if 0<=rr<h and 0<=cc<w and grid[rr][cc]==1 and (rr,cc) not in walls:
                walls.add((rr,cc)); q.append((rr,cc))
    # Shade exterior zero cells in the 8-neighbour halo of the outline.
    for r,c in walls:
        for dr in (-1,0,1):
            for dc in (-1,0,1):
                rr,cc=r+dr,c+dc
                if 0<=rr<h and 0<=cc<w and grid[rr][cc]==0 and outside[rr][cc]:
                    out[rr][cc]=2
    return out
